// Add repeatable seeded luminance noise.
export function applyGrain(data, settings = {}) {
  const amount = numberOption(settings.amount, 12, 0, 100);
  const seed = Math.floor(numberOption(settings.seed, 1, 0, 0xffffffff)) >>> 0;
