  border: 0;
  color: #777;
  font-size: 9px;
  cursor: pointer;
}
.stage {
  padding: 22px 30px 18px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.stagehead {
  height: 34px;
  margin-bottom: 12px;
}
.ratio {
  margin-left: 12px;
  color: #aaa;
  font-size: 9px;
  letter-spacing: 0.4px;
}
.hint {
  font-size: 9px;
  color: #85858e;
}
.canvaswrap {
  flex: 1;
  min-height: 300px;
  display: grid;
  place-items: center;
  position: relative;
  background: radial-gradient(ellipse, #25262c 0, #191a1f 58%, #151619 100%);
  border: 1px solid #292a30;
  border-radius: 6px;
  overflow: hidden;
  padding: 14px;
}
canvas {
  display: block;
  max-width: 100%;
  max-height: 100%;
  box-shadow: 0 18px 58px #000b, 0 0 0 1px #fff1, 0 0 34px #fb668f12;
  cursor: crosshair;
}
#toast {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  background: #22232a;
  border: 1px solid #444;
  border-radius: 4px;
  padding: 7px 12px;
  color: #e9d4df;
  font-size: 10px;
  opacity: 0;
  transition: opacity 0.2s;
  pointer-events: none;
}
#toast.show {
  opacity: 1;
}
.stagefoot {
  height: 34px;
  color: #777;
  font-size: 8px;
  letter-spacing: 0.7px;
}
@media (max-width: 900px) {
  .workspace {
    grid-template-columns: 360px 1fr;
  }
  .sidebar {
    padding: 18px;
  }
  .stage {
    padding: 16px;
  }
}
@media (max-width: 700px) {
  .top {
    padding: 0 15px;
  }
  .workspace {
    display: flex;
    flex-direction: column;
  }
  .sidebar {
    height: auto;
    overflow: visible;
    border-right: 0;
  }
  .stage {
    height: 70vh;
    min-height: 420px;
  }
  .topnote {
    font-size: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}
